import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const h=JSON.parse('{"title":"Network Optimization","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/network/index.md","filePath":"frameworks/network/index.md"}'),i={name:"frameworks/network/index.md"};function r(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="network-optimization" tabindex="-1">Network Optimization <a class="header-anchor" href="#network-optimization" aria-label="Permalink to &quot;Network Optimization&quot;">​</a></h1><p>Meet supply and demand on a directed network, respect transport/processing capacities and minimize cost. Add network construction, resource paths, structure and explicit failure scenarios later. Network is not just vehicle routing.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Topology</td><td>Node / Arc</td><td>Stable identities, endpoints and parallel services</td></tr><tr><td>Commodity and balance</td><td>Commodity / Balance</td><td>Per-commodity node balances and units</td></tr><tr><td>Capacity and cost</td><td>Capacity / Cost</td><td>Arc/shared-resource bounds and tariffs</td></tr><tr><td>Flow problem</td><td><code>FlowProblem</code></td><td>Topology, commodities, costs and resources</td></tr><tr><td>Registration/extraction</td><td><code>FlowContext</code></td><td>Conservation, capacity, cost expressions and flow results</td></tr></tbody></table><p>An integer step is a measurement increment, not an unsplittable order. Sharing resources across commodities needs physical conversions; tonnes and pieces cannot be added directly.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Standalone flow entries are Kotlin <code>NetworkFlowApplicationService</code> and Rust <code>FlowApplicationService</code>. Embed a <code>FlowContext</code> in another model instead of starting an independent optimization with unrelated variables.</p><p>Learn flow and capacity before construction and resilience. VRPTW route columns, ESPPRC and branch-and-price are advanced paths.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Parallel arcs need distinct identities, not just endpoint-based deduplication.</li><li>Connectivity does not prove transport capacity; constructed total capacity is not incremental capacity.</li><li>Explicit resilience covers supplied scenarios, not arbitrary unknown failures.</li><li>Repair timing, staffing and calendars belong to <a href="./../gantt/">Gantt</a>, not automatic Network decisions.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-flow.html">your first network flow</a>, checking conservation, costs and capacities.</li><li>Add shared resources, capacity levels, budgets and one failure scenario, changing one condition at a time.</li><li>Continue to the <a href="/ospf/examples/framework-example5.html">VRPTW integrated example</a> when routes are needed.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-network-scheduling/README.md" target="_blank" rel="noreferrer">Kotlin network domains and standalone entries</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-network-scheduling/README.md" target="_blank" rel="noreferrer">Rust network domains and proof contracts</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Shared Resources, Shortage and Embedding</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
